pm.test("Status code is 200 OK", function () {
 pm.expect(pm.response.code).to.equal(200);
});
const jsonData = pm.response.json();
pm.environment.set("apiToken", jsonData.token || jsonData.access_token);

// TIER 1: STATUS CODE & RESPONSE TIME SLA
// 1.1 Verify HTTP Status Code is 200 OK
pm.test("Tier 1: Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});
// 1.2 Verify Response Time SLA (< 1200 ms for Render Cloud Staging)
pm.test("Tier 1: Response time is within SLA (< 1200ms)", function () {
    pm.expect(pm.response.responseTime).to.be.below(1200);
});

// TIER 2: DATA INTEGRITY & BUSINESS LOGIC VERIFICATION
const jsonData = pm.response.json();
// 2.1 Verify Cart object exists in response
pm.test("Tier 2: Cart object is present in response", function () {
    pm.expect(jsonData).to.have.property("cart");
    pm.expect(jsonData.cart).to.be.an("object");
});
// 2.2 Verify Total Price is computed and greater than 0
pm.test("Tier 2: Total price is computed and greater than 0", function () {
    pm.expect(jsonData.cart).to.have.property("total");
    pm.expect(jsonData.cart.total).to.be.a("number");
    pm.expect(jsonData.cart.total).to.be.above(0);
});
// 2.3 Verify Items array exists and contains at least 1 line item
pm.test("Tier 2: Cart items array count is greater than 0", function () {
    pm.expect(jsonData.cart).to.have.property("items");
    pm.expect(jsonData.cart.items).to.be.an("array");
    pm.expect(jsonData.cart.items.length).to.be.above(0);
});
// 2.4 Verify Cart ID matches requested dynamic cartId
pm.test("Tier 2: Cart ID matches current environment cartId", function () {
    pm.expect(jsonData.cart.id).to.equal(pm.environment.get("cartId"));
});


// TIER 3: JSON SCHEMA CONTRACT VALIDATION (Ajv)
const cartSchema = {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "required": ["cart"],
    "properties": {
        "cart": {
            "type": "object",
            "required": ["id", "items", "total"],
            "properties": {
                "id": { "type": "string" },
                "total": { "type": "number" },
                "subtotal": { "type": ["number", "null"] },
                "tax_total": { "type": ["number", "null"] },
                "shipping_total": { "type": ["number", "null"] },
                "discount_total": { "type": ["number", "null"] },
                "currency_code": { "type": ["string", "null"] },
                "items": {
                    "type": "array",
                    "minItems": 1,
                    "items": {
                        "type": "object",
                        "required": ["id", "quantity", "variant_id"],
                        "properties": {
                            "id": { "type": "string" },
                            "quantity": { "type": "integer", "minimum": 1 },
                            "variant_id": { "type": "string" },
                            "unit_price": { "type": ["number", "null"] }
                        }
                    }
                }
            }
        }
    }
};
pm.test("Tier 3: JSON Schema Contract is valid", function () {
    pm.response.to.have.jsonSchema(cartSchema);
});
